package ru.mirea.callcenter.util;
import ru.mirea.callcenter.model.Appeal; import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.List;
public class CsvExporter { public void export(List<Appeal> appeals,Path file)throws IOException {Files.createDirectories(file.getParent());try(BufferedWriter w=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){w.write("id;operator_id;client_name;client_phone;topic;category;status;created_at;closed_at\n");for(Appeal a:appeals)w.write("%s;%s;%s;%s;%s;%s;%s;%s;%s%n".formatted(a.getId(),a.getOperatorId(),clean(a.getClientName()),clean(a.getClientPhone()),clean(a.getTopic()),a.getCategory(),a.getStatus(),a.getCreatedAt(),a.getClosedAt()));}}private String clean(String s){return s.replace(';',',').replace('\n',' ');}}
